/**
 * 前端 RequestMap 生成器
 * IR → 逻辑键 → 请求类型 + URL_MAP + buildPath
 *
 * 输出：src/core/services/api/generated/requestMaps.ts
 *
 * 设计原则（见 docs/frontend-contract-migration.md 决策 1/2）：
 *   - 逻辑键 = api.name 转 kebab（registerAccount → register-account）
 *   - URL_MAP_* 用 as const：keyof 编译期约束，写错键名报错
 *   - 路径参数 params 用对象 { id }：位置无关，强制
 *   - 请求/响应类型引用 @core/types/generated
 */
import { writeFileSync, mkdirSync, existsSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义的 api 段',
  '',
]

const TYPES_IMPORT = '@core/types/generated'
const METHOD_SUFFIX = { GET: 'Get', POST: 'Post', PUT: 'Put', PATCH: 'Patch', DELETE: 'Delete' }
const METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE']

const PRIM_TS = {
  string: 'string', text: 'string',
  int: 'number', long: 'number', number: 'number', decimal: 'number',
  boolean: 'boolean',
  date: 'string', datetime: 'string',
  json: 'unknown',
}

/** api.name → kebab-case 逻辑键 */
function toKebab(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()
}

function refToTs(name, resolved, imports) {
  // entity 不给前端 → unknown（设计映射，保留）
  if (resolved.kind === 'entity') return 'unknown'
  if (resolved.kind === 'enum' || resolved.kind === 'view') {
    imports.add(name)
    return name
  }
  throw new Error('无法映射前端引用类型: ' + name + '（kind=' + resolved.kind + '）')
}

function fieldToTs(fd, imports) {
  if (!fd) return 'unknown'
  if (fd.of) {
    if (PRIM_TS[fd.of]) return PRIM_TS[fd.of] + '[]'
    return refToTs(fd.of, fd.resolvedOf, imports) + '[]'
  }
  const t = fd.type
  // id 字段前端一律 string（与 types.mjs 一致）
  if (t === 'id') return 'string'
  if (PRIM_TS[t]) return PRIM_TS[t]
  return refToTs(t, fd.resolved, imports)
}

/**
 * 路径参数类型：前端 id 一律为 string（路由参数 / localStorage 都是字符串）。
 * 后端 @PathVariable Long 会自动转换，前端无需感知 long/uuid 差异。
 */
function pathParamToTs(fd, imports) {
  if (!fd) return 'string'
  if (fd.type === 'id') return 'string'
  return fieldToTs(fd, imports)
}

/** 内联对象类型（多行，baseIndent 控制缩进） */
function fieldsToTs(fields, imports, baseIndent, usePathParamType) {
  const entries = Object.entries(fields || {})
  if (entries.length === 0) return 'Record<string, never>'
  const inner = ' '.repeat(baseIndent + 2)
  const outer = ' '.repeat(baseIndent)
  const typeFn = usePathParamType ? pathParamToTs : fieldToTs
  const lines = entries.map(([fn, fd]) => {
    const opt = fd.nullable ? '?' : ''
    return inner + fn + opt + ': ' + typeFn(fd, imports)
  })
  return '{\n' + lines.join('\n') + '\n' + outer + '}'
}

function apisOfMethod(apis, method) {
  return apis.filter((a) => (a.method || 'GET').toUpperCase() === method)
}

function renderMap(method, apis, imports) {
  const suffix = METHOD_SUFFIX[method]
  const entries = apisOfMethod(apis, method)
  const lines = ['export type ' + suffix + 'RequestMap = {']
  entries.forEach((api, i) => {
    const parts = []
    if (api.output) {
      imports.add(api.output)
      parts.push('    response: ' + api.output)
    } else {
      parts.push('    response: void')
    }
    if (api.input) {
      imports.add(api.input)
      parts.push('    body: ' + api.input)
    }
    if (api.query) {
      parts.push('    query?: ' + fieldsToTs(api.query, imports, 4))
    }
    if (api.pathParams) {
      parts.push('    params: ' + fieldsToTs(api.pathParams, imports, 4, true))
    }
    const comma = i < entries.length - 1 ? ',' : ''
    lines.push('  ' + "'" + toKebab(api.name) + "'" + ': {\n' + parts.join('\n') + '\n  }' + comma)
  })
  lines.push('}')
  return lines.join('\n')
}

function renderUrlMap(method, apis) {
  const entries = apisOfMethod(apis, method)
  const lines = ['export const URL_MAP_' + method + ' = {']
  entries.forEach((api, i) => {
    const comma = i < entries.length - 1 ? ',' : ''
    lines.push("  '" + toKebab(api.name) + "': '" + api.path + "'" + comma)
  })
  lines.push('} as const')
  return lines.join('\n')
}

const BUILD_PATH = [
  '// ==================== 路径构建 ====================',
  'const URL_MAP_BY_METHOD = {',
  '  GET: URL_MAP_GET,',
  '  POST: URL_MAP_POST,',
  '  PUT: URL_MAP_PUT,',
  '  PATCH: URL_MAP_PATCH,',
  '  DELETE: URL_MAP_DELETE,',
  '} as const',
  '',
  'export const buildPath = <M extends keyof typeof URL_MAP_BY_METHOD>(',
  '  method: M,',
  '  key: keyof (typeof URL_MAP_BY_METHOD)[M],',
  '  params?: Record<string, string | number>',
  '): string => {',
  '  let url: string = URL_MAP_BY_METHOD[method][key] as string',
  '  if (params) {',
  '    Object.entries(params).forEach(([k, v]) => {',
  "      url = url.replace(':' + k, String(v))",
  '    })',
  '  }',
  '  return url',
  '}',
  '',
].join('\n')

export function generateFrontendRequestMap(ir, outDir) {
  if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true })

  const imports = new Set()
  const blocks = []

  blocks.push('// ==================== 请求类型映射 ====================')
  for (const method of METHODS) {
    blocks.push(renderMap(method, ir.apis, imports))
    blocks.push('')
  }

  blocks.push('// ==================== 逻辑键 → 物理路径 ====================')
  for (const method of METHODS) {
    blocks.push(renderUrlMap(method, ir.apis))
    blocks.push('')
  }

  blocks.push(BUILD_PATH)

  const lines = [...HEADER]
  if (imports.size > 0) {
    lines.push('import type {')
    for (const name of [...imports].sort()) lines.push('  ' + name + ',')
    lines.push("} from '" + TYPES_IMPORT + "'")
    lines.push('')
  }
  lines.push(...blocks)

  const outPath = join(outDir, 'requestMaps.ts')
  writeFileSync(outPath, lines.join('\n'), 'utf-8')
  console.log('  [frontend/requestMaps] 1 个文件 → ' + outPath)
}
